 * - Python 3.8+ installed
 * - server.py running on localhost:8000
 * - Run "python server.py" before playing the game
 *
 * USAGE IN QUIETBAKERY:
 * 1. Add this script to your Scripts folder
 * 2. In your scene, use Script command:
 *    SignDetection.connect("HELLO");
 * 3. When complete, check Switch 1 or Variable 1 for progress
 */

(function() {
    'use strict';

    // Configuration
    var serverURL = 'ws://localhost:8000/ws/detect-word';
    var completionSwitch = 1;  // Game switch ID for completion
    var progressVariable = 1;   // Game variable ID for progress

