            <style>
                #sign-detection-container {
                    position: fixed;
                    top: 5px;
                    right: 10px;
                    z-index: 1000;
                    background: linear-gradient(180deg, #2a2a2a 0%, #1a1a1a 100%);
                    border-radius: 8px;
                    padding: 8px;
                    border: 2px solid #D4A574;
                    box-shadow: 0 0 20px rgba(0,0,0,0.8), inset 0 1px 0 rgba(255,255,255,0.1);
                    font-family: 'Press Start 2P', 'Courier New', monospace;
                    display: none;
                    width: 240px;
                    max-height: 95vh;
                    overflow-y: auto;
                }
                #sign-detection-container.visible {
                    display: block;
                    animation: slideInRight 0.3s ease-out;
                }
                @keyframes slideInRight {
                    from { opacity: 0; transform: translateX(100px); }
                    to { opacity: 1; transform: translateX(0); }
                }
                #sign-camera-header {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    margin-bottom: 6px;
                    padding-bottom: 4px;
                    border-bottom: 1px solid #444;
                }
                #sign-camera-title {
                    color: #D4A574;
                    font-size: 7px;
                    text-shadow: 1px 1px 0 #000;
                }
                #sign-camera-close {
                    background: #333;
                    border: 1px solid #555;
                    color: #888;
                    font-size: 14px;
                    cursor: pointer;
                    width: 22px;
                    height: 22px;
                    border-radius: 3px;
                    transition: all 0.2s;
                    line-height: 20px;
                }
                #sign-camera-close:hover {
                    color: #fff;
                    border-color: #D4A574;
                    background: #444;
                }
                #sign-camera-wrapper {
                    position: relative;
                    border-radius: 8px;
                    overflow: hidden;
                    border: 2px solid #444;
                }
                #sign-camera-feed {
                    width: 100%;
                    max-width: 100%;
                    display: block;
                    background: #111;
                    min-height: 140px;
                    image-rendering: auto;
                    transition: opacity 0.15s ease-out;
                }
                #sign-detection-overlay {
                    position: absolute;
                    top: 5px;
                    left: 5px;
                    background: rgba(0,0,0,0.85);
                    padding: 4px 8px;
                    border-radius: 4px;
                    border: 1px solid #D4A574;
                }
                #sign-current-letter {
                    color: #D4A574;
                    font-size: 14px;
                    text-shadow: 1px 1px 0 #000;
                }
                #sign-confidence {
                    color: #888;
                    font-size: 7px;
                    margin-left: 5px;
                }
                #sign-word-progress {
                    display: flex;
                    justify-content: center;
                    gap: 3px;
                    margin: 6px 0;
                    flex-wrap: wrap;
                }
                .sign-letter-box {
                    width: 24px;
                    height: 24px;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    border-radius: 4px;
                    font-size: 9px;
                    border: 1px solid #444;
                    color: #666;
                    background: linear-gradient(180deg, #2a2a2a 0%, #1a1a1a 100%);
                    transition: all 0.2s;
                }
                .sign-letter-box.completed {
                    background: linear-gradient(180deg, #2a4a2a 0%, #1a3a1a 100%);
                    border-color: #4CAF50;
                    color: #4CAF50;
                    text-shadow: 0 0 8px rgba(76, 175, 80, 0.5);
                }
                .sign-letter-box.current {
                    border-color: #D4A574;
                    color: #fff;
                    background: linear-gradient(180deg, #3a3a3a 0%, #2a2a2a 100%);
                    box-shadow: 0 0 8px rgba(212, 165, 116, 0.3);
                }
                .sign-letter-box.current.matching {
                    background: linear-gradient(180deg, #4a3a2a 0%, #3a2a1a 100%);
                    color: #D4A574;
                    transform: scale(1.08);
                    text-shadow: 0 0 8px rgba(212, 165, 116, 0.5);
                }
                #sign-hold-bar-container {
                    background: #222;
                    border-radius: 3px;
                    margin: 6px 0;
                    padding: 2px;
                    border: 1px solid #333;
                }
                #sign-hold-bar {
                    height: 6px;
                    background: #111;
                    border-radius: 2px;
                    overflow: hidden;
                }
                #sign-hold-progress {
                    height: 100%;
                    background: linear-gradient(90deg, #D4A574 0%, #E8C49A 100%);
                    width: 0%;
                    transition: width 0.2s ease-out;
                    box-shadow: 0 0 8px rgba(212, 165, 116, 0.5);
                }
                #sign-instruction {
                    text-align: center;
                    color: #888;
                    font-size: 7px;
                    margin-top: 3px;
                    line-height: 1.3;
                }
                #sign-status-message {
                    text-align: center;
                    color: #4CAF50;
                    font-size: 8px;
                    margin-top: 5px;
                    display: none;
                    text-shadow: 0 0 8px rgba(76, 175, 80, 0.5);
                    animation: pulse 0.5s ease-in-out infinite alternate;
                }
                @keyframes pulse {
                    from { opacity: 0.8; }
                    to { opacity: 1; }
                }
                #sign-loading {
                    text-align: center;
                    color: #D4A574;
                    padding: 25px 10px;
                    font-size: 7px;
                }
                #sign-loading-spinner {
                    width: 28px;
                    height: 28px;
                    border: 2px solid #333;
                    border-top-color: #D4A574;
                    border-radius: 50%;
                    margin: 0 auto 10px;
                    animation: spin 1s linear infinite;
                }
                @keyframes spin {
                    to { transform: rotate(360deg); }
                }
                #sign-error {
                    text-align: center;
                    color: #f44336;
                    padding: 20px 10px;
                    display: none;
                }
                #sign-error-icon {
                    font-size: 28px;
                    margin-bottom: 8px;
                }
                #sign-error-title {
                    font-size: 8px;
                    margin-bottom: 6px;
                }
                #sign-error-message {
                    font-size: 7px;
                    color: #888;
                    line-height: 1.4;
                }
            </style>
            <div id="sign-camera-header">
                <span id="sign-camera-title">SIGN YOUR ANSWER</span>
                <button id="sign-camera-close">&times;</button>
            </div>
            <div id="sign-loading">
                <div id="sign-loading-spinner"></div>
                Connecting to camera...
            </div>
            <div id="sign-error">
                <div id="sign-error-icon">!</div>
                <div id="sign-error-title">Camera Error</div>
                <div id="sign-error-message">Make sure server.py is running<br>Run: python server.py</div>
            </div>
            <div id="sign-camera-content" style="display:none;">
                <div id="sign-camera-wrapper">
                    <img id="sign-camera-feed" />
                    <div id="sign-detection-overlay">
                        <span id="sign-current-letter">-</span>
                        <span id="sign-confidence">0%</span>
                    </div>
                </div>
                <div id="sign-word-progress"></div>
                <div id="sign-hold-bar-container">
                    <div id="sign-hold-bar">
                        <div id="sign-hold-progress"></div>
                    </div>
                </div>
                <p id="sign-instruction">Sign the letter and hold</p>
                <p id="sign-status-message">CORRECT! Well done!</p>
            </div>
        `;
