    function updateCameraUI() {
        if (!cameraContainer) return;
        
        // Use requestAnimationFrame for smoother updates
        if (updateScheduled) return;
        updateScheduled = true;
        
        requestAnimationFrame(function() {
            updateScheduled = false;
            
            var now = Date.now();
            var timeSinceLastUpdate = now - lastFrameUpdate;

            var content = document.getElementById('sign-camera-content');
            var loading = document.getElementById('sign-loading');
            var error = document.getElementById('sign-error');
            var feed = document.getElementById('sign-camera-feed');
            var letterDisplay = document.getElementById('sign-current-letter');
            var confidenceDisplay = document.getElementById('sign-confidence');
            var progressContainer = document.getElementById('sign-word-progress');
            var holdBar = document.getElementById('sign-hold-progress');
            var instruction = document.getElementById('sign-instruction');
            var statusMsg = document.getElementById('sign-status-message');

            // Show loading state
            if (!isConnected && !currentState.frame && !currentState.error) {
                loading.style.display = 'block';
                content.style.display = 'none';
                error.style.display = 'none';
                return;
            }

            // Show error state
            if (currentState.error) {
                loading.style.display = 'none';
                content.style.display = 'none';
                error.style.display = 'block';
                return;
            }

            // Show camera content
            loading.style.display = 'none';
            error.style.display = 'none';
            content.style.display = 'block';

            // Update camera feed - AGGRESSIVE throttling with caching
            if (currentState.frame) {
                // Only update if enough time has passed AND frame has changed
                if (timeSinceLastUpdate >= frameUpdateInterval && currentState.frame !== lastFrame) {
                    feed.src = 'data:image/jpeg;base64,' + currentState.frame;
                    lastFrame = currentState.frame;
                    lastFrameUpdate = now;
                }
            }

            // Update detected letter (always update, not throttled)
            letterDisplay.textContent = currentState.letter || '-';
            confidenceDisplay.textContent = Math.round((currentState.confidence || 0) * 100) + '%';

            // Update word progress boxes
            var targetWord = currentState.targetWord || '';
            var html = '';
            for (var i = 0; i < targetWord.length; i++) {
                var letter = targetWord[i];
                var isCompleted = i < currentState.progress;
                var isCurrent = i === currentState.progress;
                var isMatching = isCurrent && currentState.letter === letter;

                var classes = 'sign-letter-box';
                if (isCompleted) classes += ' completed';
                if (isCurrent) classes += ' current';
                if (isMatching) classes += ' matching';

                html += '<div class="' + classes + '">' + letter + '</div>';
            }
            progressContainer.innerHTML = html;

            // Update hold progress (smooth CSS transition)
            var holdPercent = (currentState.holdProgress || 0) * 100;
            holdBar.style.width = holdPercent + '%';

            // Update instruction
            if (currentState.wordComplete) {
                instruction.style.display = 'none';
                statusMsg.style.display = 'block';
            } else {
                instruction.style.display = 'block';
                statusMsg.style.display = 'none';
                instruction.textContent = 'Sign "' + (currentState.expectedLetter || '?') + '" and hold';
            }
        });
    }

    function showCamera() {
        createCameraUI();
        cameraContainer.classList.add('visible');
    }

    function hideCamera() {
        if (cameraContainer) {
            cameraContainer.classList.remove('visible');
        }
    }

    //=========================================================================
    // WebSocket Connection
    //=========================================================================

    function connect(targetWord) {
        console.log('[SignDetection] Attempting to connect with word:', targetWord);
        showCamera();

        // Reset state
        currentState = {
            letter: null,
            confidence: 0,
            progress: 0,
            total: targetWord.length,
            wordComplete: false,
            frame: null,
            expectedLetter: targetWord[0],
            holdProgress: 0,
            targetWord: targetWord.toUpperCase(),
            error: false
        };

        // Reset game data - QuietBakery compatible
        if (typeof $gameSwitches !== 'undefined') {
            $gameSwitches.setValue(completionSwitch, false);
            $gameVariables.setValue(progressVariable, 0);
        }

        updateCameraUI();

        // If already connected, just send new word
        if (ws && ws.readyState === WebSocket.OPEN) {
            ws.send(JSON.stringify({ target_word: targetWord.toUpperCase() }));
            return;
        }

        // Clean up existing connection
        if (ws) {
            ws.onopen = null;
            ws.onmessage = null;
            ws.onerror = null;
            ws.onclose = null;
            ws.close();
        }

        // Create new connection
        console.log('[SignDetection] Connecting to:', serverURL);
        ws = new WebSocket(serverURL);

        ws.onopen = function() {
            console.log('[SignDetection] Connected to server');
            isConnected = true;
            ws.send(JSON.stringify({ target_word: targetWord.toUpperCase() }));
            updateCameraUI();
        };

        ws.onmessage = function(event) {
            try {
                var data = JSON.parse(event.data);

                if (data.error) {
                    console.error('[SignDetection] Server error:', data.error);
                    currentState.error = true;
                    updateCameraUI();
                    return;
                }

                currentState = {
                    letter: data.letter,
                    confidence: data.confidence,
                    progress: data.progress,
                    total: data.total,
                    wordComplete: data.word_complete,
                    frame: data.frame,
                    expectedLetter: data.expected_letter,
                    holdProgress: data.hold_progress,
                    targetWord: data.target_word,
                    error: false
                };

                // Update game variable with progress - QuietBakery compatible
                if (typeof $gameVariables !== 'undefined') {
                    var progressPercent = Math.floor((data.progress / data.total) * 100) || 0;
                    $gameVariables.setValue(progressVariable, progressPercent);
                }

                // Word complete - set switch and auto-close
                if (data.word_complete) {
                    if (typeof $gameSwitches !== 'undefined') {
                        $gameSwitches.setValue(completionSwitch, true);
                        console.log('[SignDetection] Word complete! Switch ' + completionSwitch + ' = ON');
                    }

                    // Auto-hide after showing success
                    setTimeout(function() {
                        hideCamera();
                        disconnect();
                    }, 1500);
                }

                updateCameraUI();
            } catch (e) {
                console.error('[SignDetection] Parse error:', e);
            }
        };

        ws.onerror = function(e) {
            console.error('[SignDetection] Connection error - is server.py running on port 8000?');
            isConnected = false;
            currentState.error = true;
            updateCameraUI();
        };

        ws.onclose = function() {
            console.log('[SignDetection] Disconnected from server');
            isConnected = false;
        };
    }

    function disconnect() {
        if (ws) {
            if (ws.readyState === WebSocket.OPEN) {
                try {
                    ws.send(JSON.stringify({ command: 'stop' }));
                } catch(e) {
                    console.error('[SignDetection] Error sending stop command:', e);
                }
            }
            ws.onopen = null;
            ws.onmessage = null;
            ws.onerror = null;
            ws.onclose = null;
            ws.close();
            ws = null;
        }
        isConnected = false;
    }

    function reset() {
        if (ws && ws.readyState === WebSocket.OPEN) {
            ws.send(JSON.stringify({ command: 'reset' }));
        }
        if (typeof $gameSwitches !== 'undefined') {
            $gameSwitches.setValue(completionSwitch, false);
            $gameVariables.setValue(progressVariable, 0);
        }
        currentState.progress = 0;
        currentState.wordComplete = false;
        updateCameraUI();
    }

    //=========================================================================
    // Global API - Available to QuietBakery scripts
    //=========================================================================

    window.SignDetection = {
        connect: connect,
        disconnect: disconnect,
        reset: reset,
        show: showCamera,
        hide: hideCamera,
        getState: function() { return currentState; },
        isConnected: function() { return isConnected; },
        isComplete: function() { return currentState.wordComplete; }
    };

    console.log('[SignDetection] Plugin loaded successfully');
    console.log('[SignDetection] Use: SignDetection.connect("HELLO")');

})();

